    /*------------------------------------------------------------------------------
    --  Exercise 2.
    ------------------------------------------------------------------------------*/
    parameter SIZE_OF_ARRAY =200;
    initial begin
        int my_array[SIZE_OF_ARRAY];
        for(int i = 0; i < SIZE_OF_ARRAY; i++) begin
            if (i % 2 == 0) 
                my_array[i]=i;
            else
                my_array[i]=0;
            end
    end

    /*------------------------------------------------------------------------------
