    parameter SIZE_OF_2D_ARRAY = 10;
    initial begin
        int my_2d_array[SIZE_OF_2D_ARRAY][SIZE_OF_2D_ARRAY];
        foreach (my_2d_array[i]) begin
            foreach (my_2d_array[i][j]) begin
                my_2d_array[i][j] = (i +1) * (j + 1);
            end
        end
